def step(id, title, type, style, est, detail, why, src, requires=None, complete=None, location=None):
    d = {"id": id, "title": title, "type": type, "style": style, "estHours": est}
    if location:
        assert "\n" not in location and len(location) <= 80, id
        d["location"] = location
    d["detail"] = detail
    d["why"] = why
    if requires:
        d["requires"] = requires
    if complete:
        d["completeWhen"] = complete
    d["sources"] = src
    for s in src:
        assert s in SRC, s
    return d


